# Mutações da 228a leva (itens dbf_1, dbf_2, dbf_3). Uso: python mutacoes.py mutacoes\leva228.py --prova-save 228
MUTACOES = [
    ('dbf_continentes', '    (read == n) as i32 // continentes', '    for i in 0..n as usize { let r = records + i * 198; let p = (r + 0xbe) as *mut f64; p.write_unaligned(p.read_unaligned() + 1.0); } // mutacao: a força regional (+0xbe, double) + 1 (o nome da federação é refeito pela tradução)\n    (read == n) as i32 // continentes'),
    ('dbf_nacoes', '    (read == n) as i32 // nations', '    for i in 0..n as usize { let r = records + i * 290; let p = (r + 0xa8) as *mut f64; p.write_unaligned(p.read_unaligned() + 1.0); } // mutacao: o coeficiente FIFA (+0xa8, double) + 1\n    (read == n) as i32 // nations'),
    ('dbf_cidades', '    (read == n) as i32 // cidades', '    for i in 0..n as usize { let r = records + i * 56; *((r + 0x33) as *mut u8) = (*((r + 0x33) as *const u8)).wrapping_add(1); } // mutacao: a atração (+0x33) + 1\n    (read == n) as i32 // cidades'),
    ('dbf_estadios', '    (read == n) as i32 // stadiums', '    for i in 0..n as usize { let r = records + i * 78; let p = (r + 0x3c) as *mut i32; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: a capacidade (+0x3c) + 1\n    (read == n) as i32 // stadiums'),
    ('dbf_pessoas_157', '    (read == n) as i32 // pessoas 157', '    for i in 0..n as usize { let r = records + i * 157; let p = (r + 0x18) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: o ano de nascimento (+0x18) + 1\n    (read == n) as i32 // pessoas 157'),
    ('dbf_historico_de_pessoas', '    (read == n) as i32 // people history', '    for i in 0..n as usize { let r = records + i * 17; *((r + 0xf) as *mut u8) = (*((r + 0xf) as *const u8)).wrapping_add(1); } // mutacao: os jogos (+0xf) + 1\n    (read == n) as i32 // people history'),
    ('dbf_historicos_de_competicao', '    (read == n) as i32 // competition histories', '    for i in 0..n as usize { let r = records + i * 26; let p = (r + 0x8) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: o ano (+0x8) + 1\n    (read == n) as i32 // competition histories'),
    ('dbf_competicoes_de_pessoal', '    (read == n) as i32 // staff competitions', '    for i in 0..n as usize { let r = records + i * 101; let p = (r + 0x63) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: a reputação (+0x63) + 1\n    (read == n) as i32 // staff competitions'),
    ('dbf_historico_de_competicoes_de_pessoal', '    (read == n) as i32 // staff competition history', '    for i in 0..n as usize { let r = records + i * 58; let p = (r + 0x8) as *mut i16; p.write_unaligned(p.read_unaligned().wrapping_add(1)); } // mutacao: o ano (+0x8) + 1\n    (read == n) as i32 // staff competition history'),
]
